import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`interview-prep`,heroCta:`Get Started`,heroTitle:`Ace your next interview in minutes`,heroSubtitle:`Perplexity Computer researches your target role, generates tailored behavioral questions, and delivers a STAR-framework practice guide - automatically.`,inputUrlCta:`Prep my interview`,inputUrlPlaceholder:`e.g. Product Manager, Fintech`,inputUrlPrefill:`Go to {url} and research this role, company, and industry thoroughly. (1) Analyze the job description, required competencies, and company culture to identify the top behavioral and situational themes interviewers are likely to probe. (2) Generate 20 tailored behavioral interview questions organized by competency - leadership, problem-solving, teamwork, conflict resolution, adaptability, and role-specific skills - using the STAR framework (Situation, Task, Action, Result). (3) Write model answers for each question that reference realistic scenarios relevant to the target role and industry, with coaching notes on what interviewers are really evaluating. (4) Include follow-up prompts interviewers commonly use to dig deeper, with guidance on how to handle them. (5) Deliver a complete practice guide with a warm-up routine, timing recommendations, body language tips, and a self-scoring rubric so the candidate can track improvement across practice sessions.`,heroOverlaySteps:[`Researching your target role, industry, and key competencies`,`Generating 20 tailored behavioral questions using the STAR framework`,`Writing model answers with coaching notes and follow-up prompts`,`Practice guide with scoring rubric and session plan - ready to rehearse`],generatingSteps:[`Visiting {url} to analyze the role, company culture, and interview patterns`,`Designing an agent to generate STAR-framework questions matched to key competencies`,`Configuring model answer generation with coaching notes and follow-up prompts`,`Setting up your complete practice guide with scoring rubric and session planner`],featureSectionTitle:`From job posting to interview-ready`,featureCardTitles:[`Connects to your prep stack`,`Outputs you can rehearse`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Sheets, Notion, Gmail - Computer delivers your practice guide, question bank, and session tracker straight into the tools you already use.`,`20 behavioral questions by competency. Model STAR answers. Coaching notes on what interviewers evaluate. Follow-up prompts. Self-scoring rubric. Session planner.`],capabilitySectionTitle:`Your interview coach, on autopilot`,capabilitySectionSubtitle:`Enter your target role, step away, get a complete practice guide.`,capabilityCards:[{title:`Role & Company Research`,description:`Computer can analyze job descriptions, company culture, and industry trends to identify the exact competencies and themes interviewers will probe.`},{title:`STAR Question Generation`,description:`Computer can generate 20 behavioral questions organized by competency - leadership, teamwork, conflict, adaptability - each structured around the STAR framework.`},{title:`Model Answer Writing`,description:`Computer can write realistic model answers tailored to your target role and industry, with coaching notes explaining what interviewers are really evaluating.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Sheets, Notion, and Gmail - build workflows that keep your prep materials organized and accessible.`},{title:`Remembers Your Progress`,description:`Computer can remember your target roles, past practice sessions, and weak spots across sessions - so each round of prep builds on the last.`},{title:`New Role Alerts`,description:`Computer can monitor job boards and company pages for new postings matching your profile - and generate fresh question sets before you even ask.`}]});export{t as default};
